tasks.starter:
// 31-bit signed Smi range on 64-bit V8.
const SMI_MIN = -(2 ** 30);
const SMI_MAX = (2 ** 30) - 1;

function isSmi(n) {
  return Number.isInteger(n) && n >= SMI_MIN && n <= SMI_MAX;
}

const values = [0, 42, -1000000000, 2 ** 30, 2 ** 31, 0.5, NaN, Infinity];

let smi = 0, heap = 0;
for (const v of values) {
  if (isSmi(v)) smi++;
  else heap++;
}
console.log('smi=' + smi + ' heapnumber=' + heap);

function hash(str) {
  let acc = 0;
  for (let i = 0; i < str.length; i++) {
    acc = acc * 31 + str.charCodeAt(i); // grows unbounded -> Smi overflow -> HeapNumber
  }
  return acc;
}

model.en:
Force the accumulator back into a 32-bit integer every step with a bitwise op, so it never escapes the Smi range and TurboFan can keep its integer specialisation:<br><code>function hash(str) {
  let acc = 0;
  for (let i = 0; i &lt; str.length; i++) {
    acc = (acc * 31 + str.charCodeAt(i)) | 0; // | 0 wraps to a 32-bit signed int
  }
  return acc | 0;
}</code><br>The <code>| 0</code> coerces the intermediate (which JS computed as a double internally) back to a 32-bit signed integer each iteration. V8 recognises this idiom and keeps the value a Smi, so the loop stays on the allocation-free integer path with no per-iteration HeapNumber and no overflow deopt. (<code>Math.imul(acc, 31)</code> is the analogous fix for the multiply itself.) Confirm with <code>node --trace-deopt</code>: the bailout disappears.

model.ru:
Каждый шаг возвращай аккумулятор в 32-битное целое побитовой операцией, чтобы он никогда не выходил из диапазона Smi и TurboFan мог держать целочисленную специализацию:<br><code>function hash(str) {
  let acc = 0;
  for (let i = 0; i &lt; str.length; i++) {
    acc = (acc * 31 + str.charCodeAt(i)) | 0; // | 0 заворачивает в 32-бит знаковое
  }
  return acc | 0;
}</code><br><code>| 0</code> приводит промежуточный результат (который JS внутри посчитал как double) обратно к 32-битному знаковому целому на каждой итерации. V8 распознаёт этот идиом и держит значение Smi, поэтому цикл остаётся на целочисленном пути без аллокаций, без HeapNumber на итерацию и без деопта по переполнению. (<code>Math.imul(acc, 31)</code> — аналогичный фикс для самого умножения.) Подтверди через <code>node --trace-deopt</code>: откат исчезает.
